  ["highground.coachpreferences.click_appearance_under_battlegrounds_to_adjust_enemy.54bf82"] = "Fai clic su Aspetto sotto Campi di battaglia per modificare le file nemiche e i marcatori dei bersagli.",
  ["highground.coachpreferences.shared_appearance_controls_the_theme_fonts_and.47799d"] = "L'aspetto condiviso controlla il tema, i font e l'accessibilità per ogni addon abilitato.",
