  ["highground.coachpreferences.these_dimensions_and_row_details_belong_to.538aec"] = "Queste dimensioni e i dettagli delle righe appartengono a Campi di battaglia. Arena e Nearby hanno pagine Aspetto indipendenti.",
  ["highground.coachpreferences.bar_textures_colours_and_borders_are_shared.cbec37"] = "Le texture, i colori e i bordi delle barre sono condivisi. Regola le dimensioni di ogni pannello nella pagina Aspetto del rispettivo addon.",
  ["highground.coachpreferences.settings_live_with_their_addon.f2c359"] = "Le impostazioni stanno nel loro addon",
  ["highground.coachpreferences.use_an_addon_s_settings_appearance_commands.b1a987"] = "Usa le pagine Impostazioni, Aspetto, Comandi e Anteprime e guida di un addon. I pannelli dei campi di battaglia usano /hg bg test. Esegui /hg test o /hg test stop da Aiuto e comandi per attivare/disattivare o fermare tutte le anteprime. Panoramica e attivazione stabilisce se l'addon viene eseguito dopo il ricaricamento. Le preferenze condivise valgono per tutti gli addon.",
  ["highground.coachpreferences.keep_the_panels_you_want.abbf0b"] = "Mantieni i pannelli che desideri",
  ["highground.coachpreferences.choose_shared_preferences.f69dd0"] = "Scegli le preferenze condivise",
  ["highground.coachpreferences.checked_means_enabled_all_available_feature_switches.16b69f"] = "Spuntato significa abilitato. Qui sono mostrati tutti gli interruttori delle funzioni disponibili; scorri per vedere il resto.",
  ["highground.coachpreferences.checked_means_enabled_this_switch_shows_the.de650b"] = "Spuntato significa abilitato. Questo interruttore mostra il pulsante della minimappa di Highground.",
  ["highground.coachpreferences.choose_the_warnings_you_want.2794f4"] = "Scegli gli avvisi che desideri",
