  ["highground.coachrecords.search_by_map_result_or_character_these.9f622d"] = "Cerca per mappa, risultato o personaggio. Questi record di esempio usano la stessa finestra della cronologia delle tue partite.",
  ["highground.coachrecords.choose_a_match_to_inspect.91330e"] = "Scegli una partita da ispezionare",
  ["highground.coachrecords.select_warsong_gulch_or_arathi_basin_left.1fabad"] = "Seleziona Forra Cantaguerra o Bacino d'Arathi. Uscito in anticipo significa che il risultato non è stato rilevato; le statistiche mancanti restano mancanti.",
